cypress_script:
describe('Notification Messages', () => {
  it('should display notification messages after clicking the link', () => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    cy.get('a').contains('Click here').click();
    cy.url().should('include', '/notification_message');
    cy.get('#flash-messages').should('be.visible');
  });
  it('should not change the page URL when clicking an invalid link', () => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    cy.get('a').contains('Elemental Selenium').click();
    cy.url().should('not.include', '/notification_message');
    cy.get('#content').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Notification Messages', () => {
  test('should display notification messages after clicking the link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
    await page.click('a:has-text("Click here")');
    await expect(page).toHaveURL(/.*notification_message/);
    await expect(page.locator('#flash-messages')).toBeVisible();
  });
  test('should not change the page URL when clicking an invalid link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
    await page.click('a:has-text("Elemental Selenium")');
    await expect(page).not.toHaveURL(/.*notification_message/);
    await expect(page.locator('#content')).toBeVisible();
  });
});
